const test = require('node:test');
const assert = require('node:assert/strict');

const {validators} = require(process.env.CANDIDATE_MODULE);

const urlError = {
  name: 'Error',
  message: 'Url or Uri must start with <scheme>://',
};

function assertUrlError(value) {
  assert.throws(
    () => validators.setUrl(value),
    (error) =>
      error instanceof Error &&
      error.constructor === Error &&
      error.name === urlError.name &&
      error.message === urlError.message,
  );
}

test('setUrl rejects every tested non-string input with the ordinary URL Error', () => {
  for (const value of [undefined, null, 0, false, 1n, Symbol('url'), {}, [], () => {}]) {
    assertUrlError(value);
  }
});

test('setUrl does not access input-owned methods for non-string input', () => {
  let accessed = false;
  const value = new Proxy({}, {
    get() {
      accessed = true;
      throw new Error('input-owned method accessed');
    },
  });

  assertUrlError(value);
  assert.equal(accessed, false);
});

test('setUrl preserves its existing string acceptance policy and return value', () => {
  for (const value of [
    'http://example.com',
    'about:blank',
    'data:text/plain,hello',
    'not-a-url about:still-accepted',
    'not-a-url data:still-accepted',
  ]) {
    assert.equal(validators.setUrl(value), undefined);
  }

  for (const value of ['', 'example.com', 'about', 'data']) {
    assertUrlError(value);
  }
});

test('setNetworkConnection remains unchanged', () => {
  assert.equal(validators.setNetworkConnection(0), undefined);
  assert.throws(() => validators.setNetworkConnection(3), {
    name: 'Error',
    message: 'Network type must be one of 0, 1, 2, 4, 6',
  });
});

