'use strict';

const assert = require('node:assert/strict');
const test = require('node:test');

const {validators} = require(process.env.CANDIDATE_MODULE);

const EXPECTED_MESSAGE = 'Url or Uri must start with <scheme>://';

function assertInvalidUrl(value) {
  assert.throws(
    () => validators.setUrl(value),
    (error) =>
      error instanceof Error &&
      error.constructor === Error &&
      error.name === 'Error' &&
      error.message === EXPECTED_MESSAGE,
  );
}

test('setUrl rejects representative non-string inputs with the ordinary validation Error', () => {
  const values = [
    undefined,
    null,
    false,
    true,
    0,
    1,
    NaN,
    1n,
    Symbol('url'),
    {},
    [],
    /url/,
    new String('https://example.test'),
    () => 'https://example.test',
  ];

  for (const value of values) {
    assertInvalidUrl(value);
  }
});

test('setUrl rejects objects without accessing methods or coercion hooks', () => {
  const accessed = [];
  const input = new Proxy(
    {},
    {
      get(_target, property) {
        accessed.push(property);
        throw new Error(`unexpected property access: ${String(property)}`);
      },
    },
  );

  assertInvalidUrl(input);
  assert.deepEqual(accessed, []);
});

test('setUrl preserves the existing string acceptance policy and return value', () => {
  const accepted = [
    'https://example.test',
    'custom+scheme://resource',
    'prefix about:blank',
    'prefix data:text/plain,hello',
  ];

  for (const value of accepted) {
    assert.equal(validators.setUrl(value), undefined);
  }

  for (const value of ['', 'example.test', 'about', 'data']) {
    assertInvalidUrl(value);
  }
});

test('setNetworkConnection behavior remains intact', () => {
  for (const value of [0, 1, 2, 4, 6]) {
    assert.equal(validators.setNetworkConnection(value), undefined);
  }

  assert.throws(
    () => validators.setNetworkConnection(3),
    {name: 'Error', message: 'Network type must be one of 0, 1, 2, 4, 6'},
  );
});

