const URL_ERROR_MESSAGE = 'Url or Uri must start with <scheme>://';

function assertUrlError(value) {
  assert.throws(
    () => validators.setUrl(value),
    (error) => {
      assert.equal(Object.getPrototypeOf(error), Error.prototype);
      assert.equal(error.name, 'Error');
      assert.equal(error.message, URL_ERROR_MESSAGE);
      return true;
    },
  );
}

test('setUrl rejects non-string inputs with the ordinary URL validation error', () => {
  const values = [
    undefined,
    null,
    false,
    true,
    0,
    1,
    NaN,
    Infinity,
    1n,
    Symbol('url'),
    {},
    [],
    /url/,
    new String('https://example.test'),
    () => 'https://example.test',
  ];

  for (const value of values) {
    assertUrlError(value);
  }
});

test('setUrl does not access methods or coercion hooks owned by a non-string input', () => {
  let accesses = 0;
  const value = new Proxy(
    {},
    {
      get() {
        accesses += 1;
        throw new Error('input property accessed');
      },
    },
