const {test} = require('node:test');
const assert = require('node:assert/strict');

const {validators} = require(process.env.CANDIDATE_MODULE);

const MESSAGE = 'Url or Uri must start with <scheme>://';

const NON_STRINGS = [
  ['null', null],
  ['undefined', undefined],
  ['number', 42],
  ['zero', 0],
  ['NaN', NaN],
  ['true', true],
  ['false', false],
  ['array', ['about:']],
  ['empty array', []],
  ['plain object', {match: () => true}],
  ['function', function url() {}],
  ['bigint', 1n],
  ['boxed String', new String('about:blank')],
  ['boxed Number', new Number(1)],
  ['date', new Date()],
];

for (const [name, value] of NON_STRINGS) {
  test(`setUrl rejects non-string: ${name}`, () => {
    assert.throws(() => validators.setUrl(value), (err) => {
      assert.ok(err instanceof Error);
      assert.equal(err.constructor.name, 'Error');
      assert.equal(err.name, 'Error');
      assert.equal(err.message, MESSAGE);
      return true;
    });
  });
}

test('setUrl never invokes input-owned match method', () => {
  const evil = {
    match() {
      throw new Error('input-owned match called');
    },
  };
  assert.throws(() => validators.setUrl(evil), (err) => err.message === MESSAGE);
});

test('setUrl never coerces input via toString/valueOf/Symbol.toPrimitive', () => {
  const evil = {
    toString() {
      throw new Error('toString called');
    },
    valueOf() {
      throw new Error('valueOf called');
    },
    [Symbol.toPrimitive]() {
      throw new Error('Symbol.toPrimitive called');
    },
  };
  assert.throws(() => validators.setUrl(evil), (err) => err.message === MESSAGE);
});

test('setUrl never invokes getter properties on hostile objects', () => {
  const evil = {
    get match() {
      throw new Error('match getter called');
    },
  };
  assert.throws(() => validators.setUrl(evil), (err) => err.message === MESSAGE);
});

test('setUrl returns undefined for accepted strings', () => {
  assert.equal(validators.setUrl('http://google.com'), undefined);
});

test('setUrl preserves string acceptance policy', () => {
  const accepted = [
    'http://google.com',
    'https://example.com/path?q=1',
    'about:blank',
    'data:text/plain,hello',
    'ftp://files.example.net',
    'coap+tcp://host', // scheme chars + . -
    'my_app-scheme.v2://thing',
    'HTTP://EXAMPLE.COM',
    'page containing about: later on',
    'page containing data: later on',
    'xxx://foo/about:bar',
    'https://example.com/data:x',
    '123://weird-but-scheme-like',
  ];
  for (const url of accepted) {
    assert.doesNotThrow(() => validators.setUrl(url), `should accept: ${url}`);
  }
});

test('setUrl preserves string rejection policy', () => {
  const rejected = ['', 'http:about', 'notaurl', 'about blank', '/relative/path', 'about:'.slice(0, 5)];
  for (const url of rejected) {
    assert.throws(() => validators.setUrl(url), (err) => err.message === MESSAGE, `should reject: ${url}`);
  }
});

test('setNetworkConnection validation is unaffected', () => {
  for (const type of [0, 1, 2, 4, 6]) {
    assert.doesNotThrow(() => validators.setNetworkConnection(type));
  }
  for (const type of [3, 5, 7, -1]) {
    assert.throws(() => validators.setNetworkConnection(type),
      (err) => err.message === 'Network type must be one of 0, 1, 2, 4, 6');
  }
});

