const {test} = require('node:test');
const assert = require('node:assert');
const {validators} = require(process.env.CANDIDATE_MODULE);

const MSG = 'Url or Uri must start with <scheme>://';

function assertOrdinaryError(fn) {
  try {
    fn();
  } catch (err) {
    assert.strictEqual(err instanceof Error, true);
    assert.strictEqual(err.constructor.name, 'Error');
    assert.strictEqual(err.name, 'Error');
    assert.strictEqual(err.message, MSG);
    return;
  }
  throw new Error('Expected setUrl to throw');
}

test('rejects every non-string input with ordinary Error', () => {
  const evil = {
    match() {
      throw new Error('input-owned match invoked');
    },
    toString() {
      throw new Error('input-owned toString invoked');
    },
    valueOf() {
      throw new Error('input-owned valueOf invoked');
    },
    [Symbol.toPrimitive]() {
      throw new Error('input-owned Symbol.toPrimitive invoked');
    },
  };
  const badInputs = [
    undefined,
    null,
    42,
    0,
    NaN,
    true,
    false,
    {match: () => true},
    {toString: () => 'http://example.com'},
    evil,
    [],
    ['http://example.com'],
    () => 'http://example.com',
    new String('http://example.com'),
  ];
  for (const bad of badInputs) {
    assertOrdinaryError(() => validators.setUrl(bad));
  }
});

test('preserves string acceptance policy', () => {
  const good = [
    'http://example.com',
    'appium://settings',
    'custom+scheme-1.2://whatever',
    'about:blank',
    'data:text/plain,hello',
    'some text about: later in the string',
    'some text data: later in the string',
    'XYZ_123://',
  ];
  for (const g of good) {
    assert.doesNotThrow(() => validators.setUrl(g));
  }
  const badStrings = ['', 'no-scheme-here', 'example.com', '://nope'];
  for (const b of badStrings) {
    assertOrdinaryError(() => validators.setUrl(b));
  }
});

test('setNetworkConnection validation unaffected', () => {
  assert.doesNotThrow(() => validators.setNetworkConnection(0));
  assert.doesNotThrow(() => validators.setNetworkConnection(6));
  assert.throws(() => validators.setNetworkConnection(3), /Network type must be one of/);
});

