const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const candidateModule = process.env.CANDIDATE_MODULE;
const {ArgumentTypeError} = require(path.join(path.dirname(candidateModule), 'node_modules', 'argparse'));
const {transformers} = require(candidateModule);

function fixtureDirectory(t) {
  const directory = fs.mkdtempSync(path.join(__dirname, 'fixtures-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  return directory;
}

function nativeJsonError(value) {
  try {
    JSON.parse(value);
  } catch (error) {
    return error;
  }
  throw new Error(`Expected invalid JSON fixture: ${value}`);
}

function assertLiteralJsonError(value) {
  const cause = nativeJsonError(value);
  assert.throws(
    () => transformers.json(value),
    (error) =>
      error instanceof TypeError &&
      error.message === `The provided value must be a valid JSON. Original error: ${cause.message}` &&
      error.cause?.message === cause.message,
  );
}

function assertReadFailure(transformer, file) {
  const readMessage = 'synthetic read failure';
  const originalReadFileSync = fs.readFileSync;
  fs.readFileSync = (filePath, ...args) => {
    if (filePath === file) {
      throw new Error(readMessage);
    }
    return originalReadFileSync(filePath, ...args);
  };

  try {
    assert.throws(
      () => transformer(file),
      (error) =>
        error instanceof ArgumentTypeError &&
        error.message === `Could not read file '${file}': ${readMessage}`,
    );
  } finally {
    fs.readFileSync = originalReadFileSync;
  }
}

test('csv uses multiline parsing only for regular files', (t) => {
  const directory = fixtureDirectory(t);
  const file = path.join(directory, 'values.csv');
  const directoryPath = path.join(directory, 'directory');
  const directoryLink = path.join(directory, 'directory-link');
  const danglingLink = path.join(directory, 'dangling-link');
  const nonexistent = path.join(directory, 'nonexistent.csv');
  const probeError = path.join(file, 'child');

  fs.writeFileSync(file, ' first, ,second\nthird, fourth\n');
  fs.mkdirSync(directoryPath);
  fs.symlinkSync(directoryPath, directoryLink);
  fs.symlinkSync(path.join(directory, 'missing-target'), danglingLink);

  const expectedFile = ['first', 'second', 'third', 'fourth'];
  assert.deepStrictEqual(transformers.csv(file), expectedFile);

  for (const literal of [directoryPath, directoryLink, nonexistent, danglingLink, probeError]) {
    assert.deepStrictEqual(transformers.csv(literal), [literal]);
  }
  assert.deepStrictEqual(transformers.csv(' first, ,second '), ['first', 'second']);

  const fileLink = path.join(directory, 'file-link');
  fs.symlinkSync(file, fileLink);
  assert.deepStrictEqual(transformers.csv(fileLink), expectedFile);
  assertReadFailure(transformers.csv, file);
});

test('json uses JSON.parse for regular files and literal input otherwise', (t) => {
  const directory = fixtureDirectory(t);
  const file = path.join(directory, 'value.json');
  const fileLink = path.join(directory, 'value-link.json');
  const invalidFile = path.join(directory, 'invalid.json');
  const directoryPath = path.join(directory, 'directory');
  const directoryLink = path.join(directory, 'directory-link');
  const danglingLink = path.join(directory, 'dangling-link');
  const nonexistent = path.join(directory, 'nonexistent.json');
  const probeError = path.join(file, 'child');
  const parsed = {enabled: true, values: [1, 2], nested: {name: 'appium'}};

  fs.writeFileSync(file, JSON.stringify(parsed));
  fs.writeFileSync(invalidFile, '{');
  fs.mkdirSync(directoryPath);
  fs.symlinkSync(file, fileLink);
  fs.symlinkSync(directoryPath, directoryLink);
  fs.symlinkSync(path.join(directory, 'missing-target'), danglingLink);

  assert.deepStrictEqual(transformers.json(file), parsed);
  assert.deepStrictEqual(transformers.json(fileLink), parsed);
  for (const literal of [directoryPath, directoryLink, nonexistent, danglingLink, probeError]) {
    assertLiteralJsonError(literal);
  }

  const literal = JSON.stringify({literal: true});
  assert.deepStrictEqual(transformers.json(literal), {literal: true});

  const cause = nativeJsonError('{');
  assert.throws(
    () => transformers.json(invalidFile),
    (error) =>
      error instanceof TypeError &&
      error.message === `'${invalidFile}' must be a valid JSON. Original error: ${cause.message}` &&
      error.cause?.message === cause.message,
  );

  assertReadFailure(transformers.json, file);
});

