const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const {after, before, test} = require('node:test');

const candidatePath = process.env.CANDIDATE_MODULE;
const {parseCsvLine, transformers} = require(candidatePath);
const {ArgumentTypeError} = require(
  require.resolve('argparse', {paths: [path.dirname(candidatePath)]})
);

let fixtureDir;
let csvFile;
let csvFileLink;
let jsonFile;
let jsonFileLink;
let invalidJsonFile;
let directory;
let directoryLink;
let missingPath;
let danglingLink;

before(() => {
  fixtureDir = fs.mkdtempSync(path.join(__dirname, '.tmp-cli-transformers-'));
  csvFile = path.join(fixtureDir, 'values.csv');
  csvFileLink = path.join(fixtureDir, 'values-link.csv');
  jsonFile = path.join(fixtureDir, 'value.json');
  jsonFileLink = path.join(fixtureDir, 'value-link.json');
  invalidJsonFile = path.join(fixtureDir, 'invalid.json');
  directory = path.join(fixtureDir, 'directory');
  directoryLink = path.join(fixtureDir, 'directory-link');
  missingPath = path.join(fixtureDir, 'missing');
  danglingLink = path.join(fixtureDir, 'dangling-link');

  fs.writeFileSync(csvFile, ' alpha, beta \n\n gamma, ,delta\r\n');
  fs.writeFileSync(jsonFile, '{"source":"file","items":[1,2]}');
  fs.writeFileSync(invalidJsonFile, '{broken');
  fs.mkdirSync(directory);
  fs.symlinkSync(csvFile, csvFileLink);
  fs.symlinkSync(jsonFile, jsonFileLink);
  fs.symlinkSync(directory, directoryLink);
  fs.symlinkSync(missingPath, danglingLink);
});

after(() => {
  fs.rmSync(fixtureDir, {recursive: true, force: true});
});

test('CSV preserves literal parsing and reads regular files, including through symlinks', () => {
  assert.deepEqual(parseCsvLine(' alpha, , beta ,, gamma '), ['alpha', 'beta', 'gamma']);
  assert.deepEqual(transformers.csv(' alpha, , beta ,, gamma '), ['alpha', 'beta', 'gamma']);
  assert.deepEqual(transformers.csv(csvFile), ['alpha', 'beta', 'gamma', 'delta']);
  assert.deepEqual(transformers.csv(csvFileLink), ['alpha', 'beta', 'gamma', 'delta']);
});

test('JSON preserves literal parsing and reads regular files, including through symlinks', () => {
  assert.deepEqual(transformers.json('{"source":"literal","enabled":true}'), {
    source: 'literal',
