  });
  assert.deepEqual(transformers.json(jsonFile), {source: 'file', items: [1, 2]});
  assert.deepEqual(transformers.json(jsonFileLink), {source: 'file', items: [1, 2]});
});

test('CSV parses non-files as literal input', () => {
  for (const value of [directory, directoryLink, missingPath, danglingLink]) {
    assert.deepEqual(transformers.csv(value), [value]);
  }
});

test('JSON parses non-files as literal input and preserves parse errors and causes', () => {
  for (const value of [directory, directoryLink, missingPath, danglingLink]) {
    assert.throws(
