        assert.equal(err.constructor, TypeError);
        assert.match(err.message, /^The provided value must be a valid JSON\. Original error: /);
        assert.ok(err.cause instanceof SyntaxError);
        assert.ok(err.message.endsWith(err.cause.message));
        return true;
      }
    );
  }

  assert.throws(
    () => transformers.json(invalidJsonFile),
    (err) => {
      assert.equal(err.constructor, TypeError);
      assert.match(
