const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {transformers, parseCsvLine} = require(process.env.CANDIDATE_MODULE);

function tmpDir(t) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-transformers-'));
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  return dir;
}

function write(t, name, contents) {
  const file = path.join(tmpDir(t), name);
  fs.writeFileSync(file, contents);
  return file;
}

test('csv: parses a regular file with multiline content', (t) => {
  const file = write(t, 'list.csv', 'a,b\n c ,d\n');
  assert.deepEqual(transformers.csv(file), ['a', 'b', 'c', 'd']);
});

test('csv: follows symlink to a regular file', (t) => {
  const file = write(t, 'real.csv', 'x,y\n');
  const link = path.join(tmpDir(t), 'link.csv');
  fs.symlinkSync(file, link);
  assert.deepEqual(transformers.csv(link), ['x', 'y']);
});

test('csv: parses single-line literal CSV unchanged', (t) => {
  assert.deepEqual(transformers.csv('foo,bar,baz'), ['foo', 'bar', 'baz']);
  assert.deepEqual(transformers.csv(' a , b '), ['a', 'b']);
  assert.deepEqual(transformers.csv('a,,b'), ['a', 'b']);
  assert.deepEqual(transformers.csv(''), []);
});

test('csv: falls back to literal parsing for a directory', (t) => {
  const dir = tmpDir(t);
  assert.deepEqual(transformers.csv(dir), [dir]);
});

test('csv: falls back to literal parsing for a symlink to a directory', (t) => {
  const dir = tmpDir(t);
  const link = path.join(tmpDir(t), 'dir-link');
  fs.symlinkSync(dir, link);
  assert.deepEqual(transformers.csv(link), [link]);
});

test('csv: falls back to literal parsing for nonexistent path and dangling symlink', (t) => {
  const nonexistent = path.join(tmpDir(t), 'nope.csv');
  assert.deepEqual(transformers.csv(nonexistent), [nonexistent]);
  const dangling = path.join(tmpDir(t), 'dangling');
  fs.symlinkSync(path.join(tmpDir(t), 'missing'), dangling);
  assert.deepEqual(transformers.csv(dangling), [dangling]);
});

test('csv: read failure after regular-file detection raises ArgumentTypeError', (t, done) => {
  const file = write(t, 'secret.csv', 'a,b\n');
  fs.chmodSync(file, 0o000);
  let threw = null;
  try {
    transformers.csv(file);
  } catch (err) {
    threw = err;
  }
  fs.chmodSync(file, 0o644);
  assert.ok(threw, 'expected a throw');
  assert.equal(threw.name, 'ArgumentTypeError');
  assert.match(threw.message, new RegExp(`Could not read file '${file.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}'`));
  assert.match(threw.message, /(EACCES|EPERM)/);
  done();
});

test('json: parses a regular file and a symlink to a regular file', (t) => {
  const file = write(t, 'conf.json', '{"a": 1}');
  const link = path.join(tmpDir(t), 'link.json');
  fs.symlinkSync(file, link);
  assert.deepEqual(transformers.json(file), {a: 1});
  assert.deepEqual(transformers.json(link), {a: 1});
});

test('json: parses JSON literal unchanged', (t) => {
  assert.deepEqual(transformers.json('{"a": 1}'), {a: 1});
  assert.deepEqual(transformers.json('[1, 2]'), [1, 2]);
});

test('json: invalid literal keeps existing message and cause', (t) => {
  let threw = null;
  try {
    transformers.json('{oops}');
  } catch (err) {
    threw = err;
  }
  assert.ok(threw instanceof TypeError);
  assert.match(threw.message, /^The provided value must be a valid JSON\. Original error: /);
  assert.ok(threw.cause instanceof Error);
});

test('json: invalid file content keeps existing file message and cause', (t) => {
  const file = write(t, 'bad.json', '{oops}');
  let threw = null;
  try {
    transformers.json(file);
  } catch (err) {
    threw = err;
  }
  assert.ok(threw instanceof TypeError);
  assert.match(threw.message, new RegExp(`^'${file.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}' must be a valid JSON\\. Original error: `));
  assert.ok(threw.cause instanceof Error);
});

test('json: falls back to literal parsing for directory, symlinked directory, nonexistent path, dangling symlink', (t) => {
  const dir = tmpDir(t);
  const dirLink = path.join(tmpDir(t), 'd-link');
  fs.symlinkSync(dir, dirLink);
  const nonexistent = path.join(dir, 'nope.json');
  const dangling = path.join(tmpDir(t), 'j-dangling');
  fs.symlinkSync(path.join(tmpDir(t), 'missing.json'), dangling);
  // A path is generally not valid JSON, so the literal branch throws the
  // literal-variant message ("The provided value...") rather than the
  // file-variant message ("'<path>' must be a valid JSON").
  for (const value of [dir, dirLink, nonexistent, dangling]) {
    let threw = null;
    try {
      transformers.json(value);
    } catch (err) {
      threw = err;
    }
    assert.ok(threw instanceof TypeError, `${value} should throw TypeError`);
    assert.match(threw.message, /^The provided value must be a valid JSON\. Original error: /);
    assert.ok(threw.cause instanceof Error);
  }
});

test('json: read failure after regular-file detection raises ArgumentTypeError', () => {
  // Simulate stat-vs-read race by intercepting readFileSync through a
  // monkeypatched module is not possible with the compiled candidate; instead
  // use a directory that statSync sees as non-file (covered above) and a
  // real EACCES read via chmod where supported.
  if (process.platform === 'win32') return;
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'json-ro-'));
  try {
    const file = path.join(dir, 'conf.json');
    fs.writeFileSync(file, '{"a": 1}');
    fs.chmodSync(file, 0o000);
    let threw = null;
    try {
      transformers.json(file);
    } catch (err) {
      threw = err;
    }
    assert.ok(threw, 'expected a throw');
    assert.equal(threw.name, 'ArgumentTypeError');
    assert.match(threw.message, new RegExp(`Could not read file '${file.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}'`));
    assert.match(threw.message, /(EACCES|EPERM)/);
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

test('parseCsvLine: trimming and empty-token behavior preserved', () => {
  assert.deepEqual(parseCsvLine('a , b,c '), ['a', 'b', 'c']);
  assert.deepEqual(parseCsvLine(',,a'), ['a']);
});

