const test = require('node:test');
const assert = require('node:assert/strict');

const {validators} = require(process.env.CANDIDATE_MODULE);

const ERROR_MESSAGE = 'Url or Uri must start with <scheme>://';

function assertUrlError(input) {
  assert.throws(() => validators.setUrl(input), (error) => {
    assert.strictEqual(error.constructor, Error);
    assert.strictEqual(error.name, 'Error');
    assert.strictEqual(error.message, ERROR_MESSAGE);
    return true;
  });
}

test('setUrl rejects every representative non-string input with an ordinary Error', () => {
  const inputs = [
    undefined,
    null,
    false,
    true,
    0,
    NaN,
    1n,
    Symbol('url'),
    {},
    [],
    () => {},
    /url/,
    new String('http://example.test'),
  ];

  for (const input of inputs) {
    assertUrlError(input);
  }
});

test('setUrl does not inspect or coerce a non-string input', () => {
  let propertyReads = 0;
  const input = new Proxy({}, {
    get() {
      propertyReads += 1;
      throw new Error('input was inspected');
    },
  });

  assertUrlError(input);
  assert.strictEqual(propertyReads, 0);
});

test('setUrl preserves acceptance and return behavior for strings', () => {
  for (const url of [
    'http://example.test',
    'about:blank',
    'data:text/plain,hello',
    'prefix-about:blank',
    'prefix-data:text/plain,hello',
  ]) {
    assert.strictEqual(validators.setUrl(url), undefined);
  }
});

