const test = require('node:test');

const {validators} = require(process.env.CANDIDATE_MODULE);

const urlError = {
  name: 'Error',
  message: 'Url or Uri must start with <scheme>://',
};

function assertUrlError(action) {
  assert.throws(action, (error) => {
    assert.equal(error.constructor, Error);
    assert.equal(error.name, urlError.name);
    assert.equal(error.message, urlError.message);
    return true;
  });
}

test('setUrl rejects every non-string input with the ordinary URL error', () => {
  const inputs = [undefined, null, false, 0, 1, 1n, Symbol('url'), [], new String('http://example.com'), () => {}];

  for (const input of inputs) {
    assertUrlError(() => validators.setUrl(input));
  }
});

test('setUrl does not invoke input-owned methods for non-string inputs', () => {
  let methodCalls = 0;
  const input = {
    get match() {
      methodCalls += 1;
      throw new Error('match should not be read');
    },
    toString() {
      methodCalls += 1;
      throw new Error('toString should not be called');
    },
    valueOf() {
      methodCalls += 1;
      throw new Error('valueOf should not be called');
    },
    [Symbol.toPrimitive]() {
      methodCalls += 1;
      throw new Error('toPrimitive should not be called');
    },
  };

  assertUrlError(() => validators.setUrl(input));
  assert.equal(methodCalls, 0);
});

