const test = require('node:test');
const assert = require('node:assert/strict');

const {validators} = require(process.env.CANDIDATE_MODULE);

const URL_ERROR_MESSAGE = 'Url or Uri must start with <scheme>://';

function assertUrlError(value) {
  assert.throws(
    () => validators.setUrl(value),
    (error) => {
      assert.equal(Object.getPrototypeOf(error), Error.prototype);
      assert.equal(error.name, 'Error');
      assert.equal(error.message, URL_ERROR_MESSAGE);
      return true;
    },
  );
}

test('setUrl rejects non-string primitives with the ordinary URL error', () => {
  for (const value of [undefined, null, false, true, 0, -0, 1, NaN, Infinity, 0n, Symbol('url')]) {
    assertUrlError(value);
  }
});

test('setUrl rejects objects and functions, including boxed strings', () => {
  for (const value of [{}, [], /url/, new String('https://example.test'), () => {}, Object.create(null)]) {
    assertUrlError(value);
  }
});

test('setUrl rejects without reading methods or coercing the input', () => {
  let matchCalls = 0;
  const matchingObject = {
    match() {
      matchCalls += 1;
      return ['https://example.test'];
    },
  };
  assertUrlError(matchingObject);
  assert.equal(matchCalls, 0);

  const calls = [];
  const hostileInput = {
    get match() {
      calls.push('match');
      throw new Error('match accessed');
    },
    [Symbol.toPrimitive]() {
      calls.push('toPrimitive');
      throw new Error('coerced');
    },
    toString() {
      calls.push('toString');
      throw new Error('coerced');
    },
    valueOf() {
      calls.push('valueOf');
      throw new Error('coerced');
    },
  };

  assertUrlError(hostileInput);
  assert.deepEqual(calls, []);

  let propertyReads = 0;
  const proxiedInput = new Proxy({}, {
    get() {
      propertyReads += 1;
      throw new Error('property read');
    },
  });
  assertUrlError(proxiedInput);
  assert.equal(propertyReads, 0);
});

test('setUrl preserves accepted string forms and returns undefined', () => {
  for (const value of [
    'https://example.test',
    'custom_+.-9://destination',
    'prefix about:blank',
    'prefix data:text/plain,hello',
  ]) {
    assert.equal(validators.setUrl(value), undefined);
  }
});

test('setUrl preserves rejection of invalid strings', () => {
  for (const value of ['', 'example.test', 'https:/example.test', 'ABOUT:blank', 'DATA:text/plain,hello']) {
    assertUrlError(value);
  }
});

