const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const {transformers} = require(process.env.CANDIDATE_MODULE);

const fixtureRoot = fs.mkdtempSync(path.join(process.cwd(), '.task-tests', 'cli-transformers-'));

test.after(() => {
  fs.rmSync(fixtureRoot, {recursive: true, force: true});
});

function assertLiteralJsonError(value) {
  assert.throws(
    () => transformers.json(value),
    (error) => {
      assert.equal(error.name, 'TypeError');
      assert.match(error.message, /^The provided value must be a valid JSON\. Original error:/);
      assert.ok(error.cause);
      return true;
    },
  );
}

test('CSV and JSON load regular files, including multiline CSV', () => {
  const csvPath = path.join(fixtureRoot, 'values,from-file.csv');
  const jsonPath = path.join(fixtureRoot, 'values,from-file.json');
  const invalidJsonPath = path.join(fixtureRoot, 'invalid.json');
  fs.writeFileSync(csvPath, ' first, second\nthird,, fourth\n');
  fs.writeFileSync(jsonPath, '{"source":"file","count":2}');
  fs.writeFileSync(invalidJsonPath, '{');

  assert.deepEqual(transformers.csv(csvPath), ['first', 'second', 'third', 'fourth']);
  assert.deepEqual(transformers.json(jsonPath), {source: 'file', count: 2});
  assert.throws(
    () => transformers.json(invalidJsonPath),
    (error) => {
      assert.equal(error.name, 'TypeError');
      assert.match(error.message, new RegExp(`^'${invalidJsonPath}' must be a valid JSON\\. Original error:`));
      assert.ok(error.cause);
      return true;
    },
  );
});

test('CSV and JSON follow symlinks to regular files', () => {
  const csvPath = path.join(fixtureRoot, 'linked-values.csv');
  const jsonPath = path.join(fixtureRoot, 'linked-values.json');
  const csvLink = path.join(fixtureRoot, 'values-link.csv');
  const jsonLink = path.join(fixtureRoot, 'values-link.json');
  fs.writeFileSync(csvPath, 'alpha\nbeta');
  fs.writeFileSync(jsonPath, '{"source":"linked-file"}');
  fs.symlinkSync(csvPath, csvLink);
  fs.symlinkSync(jsonPath, jsonLink);

  assert.deepEqual(transformers.csv(csvLink), ['alpha', 'beta']);
  assert.deepEqual(transformers.json(jsonLink), {source: 'linked-file'});
});

test('CSV literals keep single-line trimming and empty-token behavior', () => {
  assert.deepEqual(transformers.csv(' first, , second ,, '), ['first', 'second']);
});

test('JSON literals keep JSON.parse output', () => {
  assert.deepEqual(transformers.json('{"source":"literal","enabled":false}'), {
    source: 'literal',
    enabled: false,
  });
});

const fallbackCases = [
  ['an existing directory', path.join(fixtureRoot, 'directory')],
  ['a symlink to a directory', path.join(fixtureRoot, 'directory-link')],
  ['a nonexistent path', path.join(fixtureRoot, 'missing-path')],
  ['a dangling symlink', path.join(fixtureRoot, 'dangling-link')],
  ['a filesystem-probe error', `${path.join(fixtureRoot, 'invalid-probe')}\0`],
];

fs.mkdirSync(fallbackCases[0][1]);
fs.symlinkSync(fallbackCases[0][1], fallbackCases[1][1]);
fs.symlinkSync(path.join(fixtureRoot, 'not-created'), fallbackCases[3][1]);

for (const [label, input] of fallbackCases) {
  test(`CSV falls back to its literal parser for ${label}`, () => {
    assert.deepEqual(transformers.csv(input), [input]);
  });

  test(`JSON falls back to its literal parser for ${label}`, () => {
    assertLiteralJsonError(input);
  });
}

test('read failures after regular-file detection remain argparse errors', () => {
  const csvPath = path.join(fixtureRoot, 'unreadable.csv');
  const jsonPath = path.join(fixtureRoot, 'unreadable.json');
  fs.writeFileSync(csvPath, 'not read');
  fs.writeFileSync(jsonPath, '{"not":"read"}');

  fs.chmodSync(csvPath, 0o000);
  fs.chmodSync(jsonPath, 0o000);
  try {
    for (const [transformer, input] of [
      [transformers.csv, csvPath],
      [transformers.json, jsonPath],
    ]) {
      assert.throws(
        () => transformer(input),
        (error) => {
          assert.equal(error.name, 'ArgumentTypeError');
          assert.match(error.message, new RegExp(`^Could not read file '${input}': `));
          assert.match(error.message, /(?:EACCES|permission denied)/i);
          return true;
        },
      );
    }
  } finally {
    fs.chmodSync(csvPath, 0o600);
    fs.chmodSync(jsonPath, 0o600);
  }
});

