'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {transformers, parseCsvLine} = require(process.env.CANDIDATE_MODULE);

test('parseCsvLine basics', () => {
  assert.deepEqual(parseCsvLine('foo,bar,baz'), ['foo', 'bar', 'baz']);
  assert.deepEqual(parseCsvLine(' a , b '), ['a', 'b']);
  assert.deepEqual(parseCsvLine(''), []);
  assert.deepEqual(parseCsvLine('foo'), ['foo']);
});

test('csv: literal input parses comma-delimited string', () => {
  assert.deepEqual(transformers.csv('foo,bar,baz'), ['foo', 'bar', 'baz']);
  assert.deepEqual(transformers.csv('foo'), ['foo']);
  assert.deepEqual(transformers.csv(' foo , bar '), ['foo', 'bar']);
  assert.deepEqual(transformers.csv(''), []);
});

test('csv: regular file wins over literal and is split on newlines', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csvtf-'));
  try {
    const file = path.join(dir, 'list.csv');
    fs.writeFileSync(file, 'foo,bar\nbaz\n');
    assert.deepEqual(transformers.csv(file), ['foo', 'bar', 'baz']);
    // a single-line file behaves like a literal
    fs.writeFileSync(file, 'foo,bar\n');
    assert.deepEqual(transformers.csv(file), ['foo', 'bar']);
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
});

test('csv: directory falls back to literal parsing', () => {
  assert.deepEqual(transformers.csv(os.tmpdir()), [os.tmpdir()]);
});

test('csv: symlink to directory falls back to literal parsing', (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csvtf-'));
  const link = path.join(dir, 'dir-link');
  fs.symlinkSync(os.tmpdir(), link);
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  assert.deepEqual(transformers.csv(link), [link]);
});

test('csv: nonexistent path and dangling symlink fall back to literal parsing', (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csvtf-'));
  const dangling = path.join(dir, 'dangling');
  fs.symlinkSync(path.join(dir, 'no-such-file'), dangling);
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  assert.deepEqual(transformers.csv(path.join(dir, 'missing.csv')), [path.join(dir, 'missing.csv')]);
  assert.deepEqual(transformers.csv(dangling), [dangling]);
});

test('csv: symlink to regular file is followed', (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csvtf-'));
  const file = path.join(dir, 'real.csv');
  fs.writeFileSync(file, 'a,b\nc\n');
  const link = path.join(dir, 'link.csv');
  fs.symlinkSync(file, link);
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  assert.deepEqual(transformers.csv(link), ['a', 'b', 'c']);
});

test('csv: read failure on regular file yields ArgumentTypeError', (t) => {
  const {ArgumentTypeError} = require(path.join(path.dirname(process.env.CANDIDATE_MODULE), '..', 'task-tools', 'node_modules', 'argparse'));
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'csvtf-'));
  const file = path.join(dir, 'noperm.csv');
  fs.writeFileSync(file, 'a,b\n');
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  if (process.platform === 'win32' || process.getuid?.() === 0) {
    t.skip('permission semantics unavailable');
    return;
  }
  fs.chmodSync(file, 0o000);
  try {
    assert.throws(
      () => transformers.csv(file),
      (err) => {
        assert.ok(err instanceof ArgumentTypeError);
        assert.match(err.message, new RegExp(`Could not read file '${file.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}'`));
        assert.ok(err.message.length > `Could not read file '${file}'`.length);
        return true;
      },
    );
  } finally {
    fs.chmodSync(file, 0o644);
  }
});

test('json: literal input parses JSON string', () => {
  assert.deepEqual(transformers.json('{"a":1}'), {a: 1});
  assert.deepEqual(transformers.json('[1,2]'), [1, 2]);
});

test('json: invalid literal keeps existing parse-error message and cause', () => {
  assert.throws(
    () => transformers.json('{nope'),
    (err) => {
      assert.ok(err instanceof TypeError);
      assert.equal(err.message, `The provided value must be a valid JSON. Original error: ${(() => {
        try { JSON.parse('{nope'); } catch (e) { return e.message; }
      })()}`);
      assert.ok(err.cause instanceof Error);
      return true;
    },
  );
});

test('json: regular file wins over literal', (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsontf-'));
  const file = path.join(dir, 'cfg.json');
  fs.writeFileSync(file, '{"a":1}');
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
  assert.deepEqual(transformers.json(file), {a: 1});
});

test('json: directory, nonexistent path, and dangling symlink fall back to literal parsing', (t) => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'jsontf-'));
  const dangling = path.join(dir, 'dangling.json');
  fs.symlinkSync(path.join(dir, 'missing.json'), dangling);
  t.after(() => fs.rmSync(dir, {recursive: true, force: true}));
