  assertRejected(undefined, 'undefined');
  assertRejected(null, 'null');
  assertRejected(false, 'false');
  assertRejected(0, 'zero');
  assertRejected(123, 'number');
  assertRejected(1.5, 'float');
  assertRejected(Number.NEGATIVE_INFINITY, 'Infinity');
  assertRejected(NaN, 'NaN');
  assertRejected(BigInt(10), 'bigint');
  assertRejected(Symbol('http://x'), 'symbol');
  assertRejected(true, 'boolean true');
  assertRejected([], 'empty array');
  assertRejected(['http://x'], 'array with url string');
  assertRejected({}, 'plain object');
  assertRejected(new Date(), 'date');
