  const directory = fs.mkdtempSync(path.join(__dirname, 'cli-transformers-'));
  t.after(() => fs.rmSync(directory, {recursive: true, force: true}));
  return directory;
}

function captureError(callback) {
  try {
    callback();
  } catch (error) {
    return error;
  }
  assert.fail('Expected callback to throw');
}

function assertLiteralJson(input) {
  const error = captureError(() => transformers.json(input));
  assert.ok(error instanceof TypeError);
  assert.match(error.message, /^The provided value must be a valid JSON\. Original error:/);
  assert.ok(error.cause instanceof SyntaxError);
  assert.ok(error.message.endsWith(error.cause.message));
}

