  fs.writeFileSync(file, ' first, ,second\n third,, \n');
  fs.symlinkSync(file, fileLink);

  assert.deepEqual(transformers.csv(file), ['first', 'second', 'third']);
  assert.deepEqual(transformers.csv(fileLink), ['first', 'second', 'third']);
  assert.deepEqual(transformers.csv(' first, ,second '), ['first', 'second']);
