    return originalLoad.call(this, request, parent, isMain);
  };
  try {
    return require(candidatePath);
  } finally {
    Module._load = originalLoad;
  }
}

function inTemporaryDirectory(run) {
  const directory = fs.mkdtempSync(path.join(__dirname, 'cli-transformers-'));
  const originalDirectory = process.cwd();
  process.chdir(directory);
  try {
    return run(directory);
  } finally {
    process.chdir(originalDirectory);
    fs.rmSync(directory, {recursive: true, force: true});
  }
}

test('CSV uses regular files before literals and preserves CSV parsing behavior', () => {
  inTemporaryDirectory(() => {
    const {transformers} = loadCandidate();
    fs.writeFileSync('file,name', ' first, second\n\n third, ,fourth\r\n');

    assert.deepEqual(transformers.csv('file,name'), ['first', 'second', 'third', 'fourth']);
    assert.deepEqual(transformers.csv(' left, , right '), ['left', 'right']);
  });
});

test('JSON uses regular files before literals and preserves JSON.parse output', () => {
  inTemporaryDirectory(() => {
