    assert.equal(transformers.json('48'), 48);
    assert.equal(transformers.json('47'), 47);
  });
});

test('filesystem probe errors fall back to literal parsing for both transformers', () => {
  const probeError = new Error('simulated probe failure');
  const {transformers} = loadCandidate({
