const assert = require('node:assert/strict');
const fs = require('node:fs');
const Module = require('node:module');
const {describe, it} = require('node:test');

const probeErrorPath = 'probe-error';
const readErrorPath = 'regular-but-unreadable';
const originalLoad = Module._load;

Module._load = function (request, parent, isMain) {
  if (request === 'node:fs') {
    return {
      ...fs,
      statSync(value, ...args) {
        if (value === probeErrorPath) {
          throw new Error('simulated probe failure');
        }
        if (value === readErrorPath) {
          return {isFile: () => true};
        }
        return fs.statSync(value, ...args);
      },
      readFileSync(value, ...args) {
        if (value === readErrorPath) {
          const error = new Error('simulated read failure');
          error.code = 'EACCES';
          throw error;
        }
        return fs.readFileSync(value, ...args);
      },
    };
  }
  return originalLoad.call(this, request, parent, isMain);
};

let transformers;
try {
  ({transformers} = require(process.env.CANDIDATE_MODULE));
} finally {
  Module._load = originalLoad;
}

describe('CLI transformer filesystem failures', () => {
  it('falls back to CSV literal parsing when the filesystem probe throws', () => {
    assert.deepEqual(transformers.csv(probeErrorPath), [probeErrorPath]);
  });

  it('falls back to the existing JSON literal error when the filesystem probe throws', () => {
    assert.throws(
      () => transformers.json(probeErrorPath),
      (error) => {
        assert.equal(error.name, 'TypeError');
        assert.match(error.message, /^The provided value must be a valid JSON\. Original error: /);
        assert.ok(error.cause instanceof SyntaxError);
        return true;
      },
    );
  });

  for (const transformer of ['csv', 'json']) {
    it(`wraps ${transformer.toUpperCase()} read failures after a regular-file probe`, () => {
      assert.throws(
        () => transformers[transformer](readErrorPath),
        (error) => {
          assert.equal(error.name, 'ArgumentTypeError');
          assert.equal(
            error.message,
            `Could not read file '${readErrorPath}': simulated read failure`,
          );
          return true;
        },
      );
    });
  }
});

