'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {transformers, parseCsvLine} = require(process.env.CANDIDATE_MODULE);
const {ArgumentTypeError} = require(
  require.resolve('argparse', {paths: [path.dirname(process.env.CANDIDATE_MODULE)]})
);

function makeTempDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'cli-transformers-'));
}

function writeFixture(dir, name, contents) {
  const filePath = path.join(dir, name);
  fs.writeFileSync(filePath, contents);
  return filePath;
}

test('csv: regular file is read and split on newlines', () => {
  const dir = makeTempDir();
  const file = writeFixture(dir, 'list.csv', 'foo,bar\r\n baz\n\nqux\n');
  assert.deepEqual(transformers.csv(file), ['foo', 'bar', 'baz', 'qux']);
});

test('csv: symlink to a regular file is followed', () => {
  const dir = makeTempDir();
  const file = writeFixture(dir, 'list.csv', 'a,b\nc\n');
  const link = path.join(dir, 'link.csv');
  fs.symlinkSync(file, link);
  assert.deepEqual(transformers.csv(link), ['a', 'b', 'c']);
});

test('csv: directory falls back to literal CSV parsing', () => {
  const dir = makeTempDir();
  assert.deepEqual(transformers.csv(`${dir},,x ,`), [dir, 'x']);
});

test('csv: symlink to a directory falls back to literal parsing', () => {
  const dir = makeTempDir();
  const link = path.join(dir, 'dirlink');
  fs.symlinkSync(dir, link);
  assert.deepEqual(transformers.csv(link + ' ,foo'), [link, 'foo']);
});

test('csv: nonexistent path falls back to literal parsing', () => {
  const missing = path.join(makeTempDir(), 'nope.csv');
  assert.deepEqual(transformers.csv(missing + ',bar'), [missing, 'bar']);
});

test('csv: dangling symlink falls back to literal parsing', () => {
  const dir = makeTempDir();
  const link = path.join(dir, 'dangling');
  fs.symlinkSync(path.join(dir, 'missing-target'), link);
  assert.deepEqual(transformers.csv(link), [link]);
});

test('csv: literal parsing keeps trimming and empty-token behavior', () => {
  assert.deepEqual(transformers.csv(' foo , ,bar '), ['foo', 'bar']);
  assert.deepEqual(transformers.csv(',,,'), []);
});

test('csv: file-first precedence uses file contents over the literal', () => {
  const dir = makeTempDir();
  const file = writeFixture(dir, 'looks-like-csv', '1,2');
  assert.deepEqual(transformers.csv(file), ['1', '2']);
});

test('csv: read failure on an identified regular file becomes ArgumentTypeError', () => {
  const dir = makeTempDir();
  const file = writeFixture(dir, 'secret.csv', 'a,b');
  fs.chmodSync(file, 0o000);
  try {
