    () => transformers.json(missing),
    (err) => {
      assert.ok(err instanceof TypeError);
      assert.equal(err.message, `The provided value must be a valid JSON. Original error: ${err.cause.message}`);
      return true;
    }
  );
});

test('json: dangling symlink falls back to literal JSON parsing', () => {
  const dir = makeTempDir();
