const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const {transformers, parseCsvLine} = require(process.env.CANDIDATE_MODULE);
const ArgumentTypeError = require(
  path.join(path.dirname(process.env.CANDIDATE_MODULE), 'node_modules', 'argparse')
).ArgumentTypeError;

function makeFixture() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'cli-transformers-'));
  const file = (name, contents) => {
    const p = path.join(dir, name);
    fs.writeFileSync(p, contents);
    return p;
  };
  return {
    dir,
    file,
    csvFile: file('list.csv', 'a,b\n  c , d \n\ne\n'),
    jsonFile: file('obj.json', '{"a":1,"b":["x"]}\n'),
    subDir: fs.mkdtempSync(path.join(dir, 'sub-')),
  };
}

const fixtures = makeFixture();

test('csv: multiline file is split on newlines and commas', () => {
  assert.deepEqual(transformers.csv(fixtures.csvFile), ['a', 'b', 'c', 'd', 'e']);
});

test('csv: single-line literal keeps trim/empty-token behavior', () => {
  assert.deepEqual(transformers.csv('foo, bar ,baz'), ['foo', 'bar', 'baz']);
  assert.deepEqual(transformers.csv('foo,,bar,'), ['foo', 'bar']);
  assert.deepEqual(parseCsvLine(' foo , '), ['foo']);
});

test('csv: directory and nonexistent path fall back to literal parsing', () => {
  assert.deepEqual(transformers.csv(fixtures.subDir), [fixtures.subDir]);
  assert.deepEqual(transformers.csv(path.join(fixtures.dir, 'no-such.csv')), [path.join(fixtures.dir, 'no-such.csv')]);
});

test('csv: dangling symlink falls back to literal parsing', () => {
  const dangling = path.join(fixtures.dir, 'dangling.csv');
  fs.symlinkSync(path.join(fixtures.dir, 'missing.csv'), dangling);
  assert.deepEqual(transformers.csv(dangling), [dangling]);
});

test('csv: symlink to a regular file is followed', () => {
  const link = path.join(fixtures.dir, 'link.csv');
  fs.symlinkSync(fixtures.csvFile, link);
  assert.deepEqual(transformers.csv(link), ['a', 'b', 'c', 'd', 'e']);
});

test('json: file content is parsed', () => {
  assert.deepEqual(transformers.json(fixtures.jsonFile), {a: 1, b: ['x']});
});

test('json: literal JSON string is parsed', () => {
  assert.deepEqual(transformers.json('{"k":"v"}'), {k: 'v'});
});

test('json: directory and nonexistent path fall back to literal parsing', () => {
  assert.throws(
    () => transformers.json(fixtures.subDir),
    (err) => err instanceof TypeError && /must be a valid JSON\. Original error: /.test(err.message) && err.cause instanceof Error
  );
  assert.throws(
    () => transformers.json(path.join(fixtures.dir, 'no-such.json')),
    (err) => err instanceof TypeError && /The provided value must be a valid JSON\. Original error: /.test(err.message)
  );
});

test('json: dangling symlink falls back to literal parsing', () => {
  const dangling = path.join(fixtures.dir, 'dangling.json');
  fs.symlinkSync(path.join(fixtures.dir, 'missing.json'), dangling);
  assert.throws(
    () => transformers.json(dangling),
    (err) => err instanceof TypeError && /The provided value must be a valid JSON\. Original error: /.test(err.message)
  );
});

test('json: symlink to a regular file is followed', () => {
  const link = path.join(fixtures.dir, 'link.json');
  fs.symlinkSync(fixtures.jsonFile, link);
  assert.deepEqual(transformers.json(link), {a: 1, b: ['x']});
});

if (process.getuid && process.getuid() !== 0) {
  test('json: read failure on a regular file throws ArgumentTypeError, not literal fallback', () => {
    const unreadable = path.join(fixtures.dir, 'unreadable.json');
    fs.writeFileSync(unreadable, '{"secret":1}');
    fs.chmodSync(unreadable, 0o000);
    assert.throws(
      () => transformers.json(unreadable),
      (err) => err instanceof ArgumentTypeError && new RegExp(`Could not read file '${unreadable}'`).test(err.message)
    );
  });

  test('csv: read failure on a regular file throws ArgumentTypeError, not literal fallback', () => {
    const unreadable = path.join(fixtures.dir, 'unreadable.csv');
    fs.writeFileSync(unreadable, 'a,b');
    fs.chmodSync(unreadable, 0o000);
    assert.throws(
      () => transformers.csv(unreadable),
      (err) => err instanceof ArgumentTypeError && new RegExp(`Could not read file '${unreadable}'`).test(err.message)
    );
  });
}
